package com.bookstore.bike.controller;
import com.bookstore.bike.entity.*; import com.bookstore.bike.repo.*; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.web.bind.annotation.*; import java.math.*; import java.time.*; import java.time.temporal.ChronoUnit; import java.util.*;
@RestController @RequestMapping("/api/bookings") public class BookingController {final BookingRepository bookings;final BikeRepository bikes;final UserRepository users; BookingController(BookingRepository b,BikeRepository bi,UserRepository u){bookings=b;bikes=bi;users=u;} public record Create(@NotNull Long bikeId,@NotNull Instant startAt,@NotNull Instant endAt,String pickupLocation,String returnLocation){}
 @PostMapping public ResponseEntity<?> create(@RequestBody Create r){User u=me();Bike b=bikes.findById(r.bikeId()).orElseThrow();if(u.getVerificationStatus()!=Enums.VerificationStatus.VERIFIED)return ResponseEntity.status(403).body(Map.of("error","Student verification is required before booking"));if(b.getOwner().getId().equals(u.getId()))return ResponseEntity.badRequest().body(Map.of("error","You cannot book your own bike"));if(r.startAt().isBefore(Instant.now())||!r.endAt().isAfter(r.startAt()))return ResponseEntity.badRequest().body(Map.of("error","Choose a valid future rental period"));if(b.getAvailability()!=Enums.AvailabilityStatus.AVAILABLE||bookings.overlaps(b.getId(),r.startAt(),r.endAt()))return ResponseEntity.status(409).body(Map.of("error","Bike is unavailable for these dates"));long hours=Math.max(1,ChronoUnit.HOURS.between(r.startAt(),r.endAt()));Booking x=new Booking();x.setStudent(u);x.setBike(b);x.setStartAt(r.startAt());x.setEndAt(r.endAt());x.setRentalAmount(b.getPricePerHour().multiply(BigDecimal.valueOf(hours)));x.setDeposit(b.getDepositAmount());x.setTotalAmount(x.getRentalAmount().add(x.getDeposit()));x.setPickupLocation(r.pickupLocation());x.setReturnLocation(r.returnLocation());return ResponseEntity.status(201).body(bookings.save(x));}
 @GetMapping("/my") public List<Booking> mine(){return bookings.findByStudentIdOrderByStartAtDesc(me().getId());} private User me(){return users.findByEmail(SecurityContextHolder.getContext().getAuthentication().getName()).orElseThrow();}}
